def connected(g):
    H=len(g); W=len(g[0])
    seen=set(); out=[list(r) for r in g]
    comps=[]
    for r in range(H):
        for c in range(W):
            if g[r][c] and (r,c) not in seen:
                col=g[r][c]; stack=[(r,c)]; comp=[]
                while stack:
                    y,x=stack.pop()
                    if (y,x) in seen or g[y][x]!=col: continue
                    seen.add((y,x)); comp.append((y,x))
                    for dy in(-1,0,1):
                        for dx in(-1,0,1):
                            a,b=y+dy,x+dx
                            if 0<=a<H and 0<=b<W: stack.append((a,b))
                comps.append(comp)
    return comps
